  var stats = [[ov.books, 'books', '#books'], [ov.marginalia, 'marginalia', '#notebook'], [ov.arcs, 'arcs', '#arcs'], [ov.subTheories, 'sub-theories', '#arcs'], [ov.published, 'published', '#arcs']];
