var CAP_MOUNTED = false;
function initCaptureDoor() {
  if (CAP_MOUNTED) { return; }
  if (!document.body) { return; }
  CAP_MOUNTED = true;
  buildCaptureDoor();
  nbInstallDraftHooks(); // reuse the shipped visibilitychange/pagehide flush infra

  // BLOCK 1: the door is mounted ONCE and never torn down on auth-change (unlike
  // the notebook composer, which renderRoute rebuilds). On a uid change, reset EVERY
  // path that could carry one account's content to another — the field, the sheet,
  // the mic, AND the Undo toast + capLastFiled + the caught-this-session list (the
  // gate re-check found these three were the leak's un-audited side door).
  if (window.firebase && firebase.auth) {
    try {
      firebase.auth().onAuthStateChanged(function (au) {
        var newUid = au ? au.uid : null;
        if (newUid === capOwnerUid) { return; }
        var prevUid = capOwnerUid;
        capOwnerUid = newUid;
        // defuse any pending debounced draft-save: with capOwnerUid now reassigned it
        // would pass capSaveDraftNow's guard and write the (about-to-be-cleared, empty)
        // field under the NEW owner's key — silently wiping their prior draft. Cancel it
        // in BOTH branches; the adopt branch persists explicitly below.
        if (capDraftTimer) { window.clearTimeout(capDraftTimer); capDraftTimer = null; }
        if (prevUid === null) {
          // signed-out -> signed-in: the on-screen text was typed anonymously by the
          // person who just authenticated as THEMSELVES — ADOPT it (a "type while
          // logged out, then sign in to save" flow keeps the draft), persisting it
          // under the now-correct owner. Never wipe it; this is not a cross-account case.
          var f0 = capEl('capField');
          if (newUid && f0 && capTrim(f0.value)) { capSaveDraftNow(); }
          return;
        }
        // prevUid was a REAL account and it changed -> all on-screen/in-memory capture
        // state belongs to the PREVIOUS account; reset every path (BLOCK 1, all doors).
        if (capMicSession) { try { capMicSession.stop(); } catch (e) {} capMicSession = null; capMicSeq = capMicSeq + 1; }
        capClearStaged(); // CD-6: drop the prior owner's staged photos. Do NOT release capCommitBusy here — an in-flight image commit's own gen-gated finalize/backstop releases it; force-releasing mid-put would let the new owner's commit start while the prior put is still outstanding (the double-write race the gen-token guards).
        var ff = capEl('capField'), sh = capEl('capSheet');
        if (ff) { ff.value = ''; capAutogrow(); }
        if (sh && sh.classList.contains('is-open')) {
          capEl('capScrim').classList.remove('is-open'); sh.classList.remove('is-open');
          var navX = document.querySelector('.cap-nav-entry'); if (navX) { navX.setAttribute('aria-current', 'false'); }
        }
        var tt = capEl('capToast'); if (tt) { tt.classList.remove('is-show'); }
        if (capToastTimer) { window.clearTimeout(capToastTimer); capToastTimer = null; }
        capLastFiled = null;
        // DOOR-SEG (cross-account): the pending split review AND its ephemeral parent-snapshot Undo
        // belong to the PREVIOUS account — drop both, and bump the gen so any in-flight segmentDoc
        // result drops itself (its own owner-check already would; this is belt-and-suspenders). This
        // is the "picker-open-during-owner-change" surface (condition 3).
        capSplitGen = capSplitGen + 1;
        capSplitState = null; capSplitUndo = null;
        if (capSplitPopOutside) { document.removeEventListener('click', capSplitPopOutside, true); capSplitPopOutside = null; }
        if (capEl('capSplit')) { capEl('capSplit').hidden = true; capEl('capSplit').innerHTML = ''; }
        capCaught = []; capRenderCaught();
      });
    } catch (e) {}
  }

  // keep the create-door clear of the Shelf FAB across route changes (gate fix)
  capUpdateCreateDoorPos();
  window.addEventListener('hashchange', capUpdateCreateDoorPos);

  var field = capEl('capField');
  field.addEventListener('input', function () { capAutogrow(); capScheduleDraftSave(); });
  field.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); capCommit(); }
  });

  // mode chips
  var modes = document.querySelectorAll('.capdoor-mode'), i;
  for (i = 0; i < modes.length; i++) {
    (function (b) { b.addEventListener('click', function () { capSetMode(b.getAttribute('data-mode')); }); })(modes[i]);
  }
  // register chips
  var segs = document.querySelectorAll('.capdoor-seg button');
  for (i = 0; i < segs.length; i++) {
    (function (b) { b.addEventListener('click', function () { capSetRegister(b.getAttribute('data-r')); capEl('capField').focus(); }); })(segs[i]);
  }
  // context chip
  capEl('capChipBtn').addEventListener('click', function () {
    var ctx = capEl('capContext');
    var open = ctx.classList.toggle('is-open');
    this.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open) { capRenderChipPop(); }
  });
  document.addEventListener('click', function (e) {
    var ctx = capEl('capContext');
    if (ctx && !ctx.contains(e.target)) { ctx.classList.remove('is-open'); capEl('capChipBtn').setAttribute('aria-expanded', 'false'); }
  });

  // summons
  capEl('capCreateDoor').addEventListener('click', function () { capOpen({ mode: 'note' }); });
  var navEntry = document.querySelector('.cap-nav-entry');
  if (navEntry) { navEntry.addEventListener('click', function (e) { e.preventDefault(); capOpen({ mode: 'note' }); }); }

  // close (CD-5: explicit only)
  capEl('capClose').addEventListener('click', capClose);
  // scrim click does NOT close — nudge the veil (CD-5, ruled)
  capEl('capScrim').addEventListener('click', function () {
    if (!capEl('capSheet').classList.contains('is-open')) { return; }
    var sc = capEl('capScrim');
    if (!capPrefersReduced()) { sc.classList.remove('is-nudge'); void sc.offsetWidth; sc.classList.add('is-nudge'); }
  });
  // commit
  capEl('capCommit').addEventListener('click', capCommit);

  // drag-to-dismiss (mobile handle)
  var handle = capEl('capHandle'), dragStartY = null, dragDelta = 0, sheet = capEl('capSheet');
  handle.addEventListener('pointerdown', function (e) { try { handle.setPointerCapture(e.pointerId); } catch (err) {} dragStartY = e.clientY; dragDelta = 0; sheet.style.transition = 'none'; });
  handle.addEventListener('pointermove', function (e) {
    if (dragStartY === null) { return; }
    dragDelta = Math.max(0, e.clientY - dragStartY);
    sheet.style.transform = 'translateY(' + dragDelta + 'px)';
  });
  function dragEnd() {
    if (dragStartY === null) { return; }
    sheet.style.transition = ''; sheet.style.transform = '';
    if (dragDelta > 90) { capClose(); }
    dragStartY = null; dragDelta = 0;
  }
  handle.addEventListener('pointerup', dragEnd);
  handle.addEventListener('pointercancel', dragEnd);

  // keyboard: Escape closes (explicit keypress, not automatic); ⌘N summons
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && capEl('capSheet').classList.contains('is-open')) { capClose(); return; }
    if ((e.metaKey || e.ctrlKey) && (e.key === 'n' || e.key === 'N')) { e.preventDefault(); capOpen({ mode: 'note' }); }
  });

  // paste/import: real file read, no network
  capEl('capUploadBtn').addEventListener('click', function () { capEl('capFileInput').click(); });
  capEl('capFileInput').addEventListener('change', function () {
    var fl = this.files && this.files[0];
    if (!fl) { return; }
    var ownerAtRead = capOwnerUid; // BLOCK 1 (re-check #4): a FileReader read can span an account switch
    var reader = new FileReader();
    reader.onload = function () {
      // Drop on ANY owner change since the read began — exact match only. A real->real
      // switch is the direct leak; a real->null (sign-out) would otherwise re-seed the
      // field so a later sign-in ADOPTS A's file as B. Conservative-safe: a rare
      // signed-out-upload-then-sign-in drops the file (re-uploadable), never leaks it.
      if (capOwnerUid !== ownerAtRead) { return; }
      field.value = String(reader.result || ''); capAutogrow(); capScheduleDraftSave(); field.focus();
    };
    reader.readAsText(fl);
    this.value = '';
  });

  // CD-6 photo mode (migrated writeline image path): the attach pills fire the hidden
  // file inputs; each chosen image downscales to a JPEG blob, previews inline, and is
  // stored to IndexedDB on commit as a note.images ref via the shared captureNote path.
  var camIn = capEl('capCamInput'), libIn = capEl('capLibInput');
  capEl('capPhotoCam').addEventListener('click', function () { camIn.click(); });
  capEl('capPhotoLib').addEventListener('click', function () { libIn.click(); });
  camIn.addEventListener('change', function () { capAddStagedPhoto(this.files && this.files[0]); this.value = ''; });
  libIn.addEventListener('change', function () { capAddStagedPhoto(this.files && this.files[0]); this.value = ''; });

  // CD-6 voice mode (Lane 2): reuse the shipped dictation transport. The transcript
  // writes into the SHARED field the instant it exists (draft-persisted), then is
  // filed via the sheet like any note (never processDictation's own commit path).
  // Loss window = mic-tap → rec.onstop only, bounded + disclosed in the hero copy.
  var mic = capEl('capMic');
  mic.addEventListener('click', function () {
    if (!(window.ImportCapture && ImportCapture.recordAndTranscribe)) { return; }
    if (capMicSession) { capMicSession.stop(); return; } // second tap = stop
    var listenState = capEl('capListenState'), micLabel = capEl('capMicLabel'), sheet = capEl('capSheet');
    if (!ImportCapture.canRecord()) { micLabel.textContent = 'Recording not supported here — type below'; return; }
    capMicSeq = capMicSeq + 1;
    var mySeq = capMicSeq; // BLOCK 2: this recording's token; a callback drops itself if superseded
    mic.classList.add('is-listening'); sheet.classList.add('cap-mic-active');
    listenState.textContent = 'STARTING…'; micLabel.textContent = 'Warming up…';
    capMicSession = ImportCapture.recordAndTranscribe({
      onStart: function () { if (mySeq !== capMicSeq) { return; } listenState.textContent = 'LISTENING…'; micLabel.textContent = 'Listening… tap to stop'; },
      onTranscribing: function () { if (mySeq !== capMicSeq) { return; } mic.classList.remove('is-listening'); sheet.classList.remove('cap-mic-active'); listenState.textContent = 'TRANSCRIBING…'; micLabel.textContent = 'Transcribing…'; },
      onResult: function (text) {
        if (mySeq !== capMicSeq) { return; } // stale: the recording was abandoned (mode-change/close/superseded) — drop the transcript
        capMicSession = null;
        var t = capTrim(text || '');
        if (t) { field.value = field.value ? (field.value + (/\s$/.test(field.value) ? '' : ' ') + t) : t; capAutogrow(); capScheduleDraftSave(); }
        listenState.textContent = ''; micLabel.textContent = 'Review below, or tap to talk again';
        field.focus();
      },
      onError: function (reason) {
        if (mySeq !== capMicSeq) { return; }
        capMicSession = null; mic.classList.remove('is-listening'); sheet.classList.remove('cap-mic-active'); listenState.textContent = '';
        micLabel.textContent = (reason === 'denied') ? 'Mic permission denied — type below'
          : (reason === 'unsupported') ? 'Recording not supported here — type below'
          : (reason === 'empty') ? 'Nothing recorded — tap to try again'
          : 'Transcription failed — type below';
      }
    });
  });

  // CD-4 talk-it-through: inert seat, shows a tooltip, never opens chat
  var talk = capEl('capTalkSeat');
  talk.addEventListener('click', function () {
    talk.classList.add('show-tip');
    window.setTimeout(function () { talk.classList.remove('show-tip'); }, 1800);
  });

  // CA-2 flush: keep the sheet's own draft current when the tab hides
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden' && capEl('capSheet').classList.contains('is-open')) { capSaveDraftNow(); }
  });
  window.addEventListener('pagehide', function () { if (capEl('capSheet').classList.contains('is-open')) { capSaveDraftNow(); } });
}
// public summon — e.g. openCaptureDoor({ targetKey: bookId, mode: 'note' })
function openCaptureDoor(opts) { if (!CAP_MOUNTED) { initCaptureDoor(); } capOpen(opts || {}); }

// Lane 3 — Android share_target landing (GET, text-only). The manifest's
// share_target action is "/", so a share arrives as ?title=&text=&url= on cold
// open. The router is 100% hash-based (zero location.search elsewhere), so this is
// net-new plumbing scoped to the share case only: compose the shared bits, open the
// door pre-filled, then strip the query so a reload never re-fires it. No-op when
// there is no share payload (the normal cold open). File/image share = NO-GO (the
// SW bails on non-GET); iOS = NO-GO (WebKit has no share_target) — GET-text only.
function capHandleShareTarget() {
  var s = location.search || '';
  if (!s || s.indexOf('=') === -1) { return; }
  var params = {}, pairs = s.replace(/^\?/, '').split('&'), i, eq, pk, pv;
  for (i = 0; i < pairs.length; i = i + 1) {
    eq = pairs[i].indexOf('=');                 // NOTE 3: split on the FIRST '=' only
    pk = (eq === -1) ? pairs[i] : pairs[i].slice(0, eq);
    pv = (eq === -1) ? '' : pairs[i].slice(eq + 1);
    if (pk) {
      try { params[decodeURIComponent(pk)] = decodeURIComponent(pv.replace(/\+/g, ' ')); } catch (e) {}
    }
  }
  var title = params.title || '', text = params.text || '', url = params.url || '';
  if (!title && !text && !url) { return; }
  var parts = [];
  if (title && title !== text) { parts.push(title); }
  if (text) { parts.push(text); }
  if (url && text.indexOf(url) === -1) { parts.push(url); }
  var body = capTrim(parts.join('\n'));
  // strip the query so a reload does not re-open the share (keep the hash route)
  if (window.history && history.replaceState) {
    try { history.replaceState(null, '', location.pathname + location.hash); } catch (e2) {}
  }
  if (!body) { return; }
  if (!CAP_MOUNTED) { initCaptureDoor(); }
  capOpen({ mode: 'note' });
  var f = capEl('capField');
  f.value = f.value ? (f.value + '\n' + body) : body;
  capAutogrow();
  capScheduleDraftSave();
}

window.views = {
  initCaptureDoor:       initCaptureDoor,
  openCaptureDoor:       openCaptureDoor,
  capHandleShareTarget:  capHandleShareTarget,
  renderRoute:           renderRoute,
  drainCommonsExits:     drainCommonsExits,
  renderAbout:           renderAbout,
  renderNotebook:        renderNotebook,
  renderShelf:           renderShelf,
  renderBookDetail:      renderBookDetail,
  renderBookView:        renderBookView,
  renderArtifact:        renderArtifact,
  openJournalEditor:     openJournalEditor,
  openMarginaliaEditor:  openMarginaliaEditor,
  openShelfEditor:       openShelfEditor,
  openNotebookSettings:  openNotebookSettings,
  setRegisterDefault:    setRegisterDefault,
  openTransparencyView:  openTransparencyView,
  closeTransparencyView: closeTransparencyView
};

console.log('views.js loaded');
